using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AmbushEffect", menuName = "Data/Battle/Effects/Ambush Effect")]
public class AmbushEffect : Effect
{
	[Header("Ambush Effect")]
	[SerializeField]
	private CorruptedAnimalEffectsList corruptedAnimalEffectsList;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedAtTheStartOfTheBattle = base.localizationManager.GetLocalizedAtTheStartOfTheBattle(withSpace: true);
		string localizedEnemyEffectOwnerReceiveEffectFormatted = base.localizationManager.GetLocalizedEnemyEffectOwnerReceiveEffectFormatted(corruptedAnimalEffectsList.HiddenEffect, EffectsValues.INFINITY);
		return Smart.Format(GetLocalizedDescription(), localizedAtTheStartOfTheBattle + localizedEnemyEffectOwnerReceiveEffectFormatted);
	}
}
